const data = $json;

return data.cards.map(card => ({
  json: {
    article_id: data.article_id,
    platform: data.platform,

    core_text: data.core_text,

    recommended_card_count:
      data.recommended_card_count,

    card_count_reason:
      data.card_count_reason,

    card_id: card.card_id,
    page: card.page,
    role: card.role,

    content: {
      keyword: card.content?.keyword || '',
      headline: card.content?.headline || '',
      body: card.content?.body || ''
    },

    source_evidence:
      Array.isArray(card.source_evidence)
        ? card.source_evidence
        : [],

    image: {
      editable: card.image?.editable !== false,
      selected_image_url:
        card.image?.selected_image_url || ''
    }
  }
}));

return items.map(item => {
  const card = item.json;

  return {
    json: {
      article_id: card.article_id,

      card_id: card.card_id,

      page: card.page,

      template: card.template,

      size: {
        width: 1080,
        height: 1350
      },

      content: {
        keyword: card.content?.keyword || '',
        headline: card.content?.headline || '',
        body: card.content?.body || ''
      },

      image: {
        type: card.image?.type || 'none',
        url: card.image?.url || ''
      },

      evidence: card.evidence || {}
    }
  };
});

const data = $json;

if (!data.article_id) {
  throw new Error(
    `article_id가 없습니다. 현재 입력: ${JSON.stringify(data)}`
  );
}

if (!data.output) {
  throw new Error(
    `output이 없습니다. 현재 입력: ${JSON.stringify(data)}`
  );
}

if (!Array.isArray(data.output.cards)) {
  throw new Error(
    `output.cards가 배열이 아닙니다. 현재 output: ${JSON.stringify(data.output)}`
  );
}

if (data.output.cards.length === 0) {
  throw new Error('렌더링할 카드가 없습니다.');
}

return [
  {
    json: {
      article_id: data.article_id,

      platform: data.platform || 'instagram',

      status: data.status || 'ready_for_render',

      core_text: data.output.core_text || {},

      recommended_card_count:
        data.output.recommended_card_count || data.output.cards.length,

      card_count_reason:
        data.output.card_count_reason || '',

      cards: data.output.cards
    }
  }
];
